# AI Office v2.5 Part K End-to-End Intelligence Certification Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found." }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.5-part-k-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @("config\intelligence","scripts\intelligence","workspace\templates","workspace\intelligence\certifications","docs")) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
    param([string]$RelativePath,[string]$Base64Content)
    $Destination = Join-Path $Repository $RelativePath
    $Parent = Split-Path -Parent $Destination
    if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        $BackupPath = Join-Path $BackupDirectory $RelativePath
        $BackupParent = Split-Path -Parent $BackupPath
        if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
    }
    [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
    Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\intelligence\end-to-end-certification-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\templates\intelligence-certification-template.json" -Base64Content "ewogICJjZXJ0aWZpY2F0aW9uX2lkIjogIiIsCiAgInZlcnNpb24iOiAiMi41LjAiLAogICJyZWxlYXNlX25hbWUiOiAiSW50ZWxsaWdlbmNlIFVwZ3JhZGUiLAogICJzdGF0dXMiOiAiIiwKICAicGFzc2VkX2NoZWNrcyI6IDAsCiAgImZhaWxlZF9jaGVja3MiOiAwLAogICJjaGVja3MiOiBbXSwKICAiY2VydGlmaWVkX2F0IjogIiIKfQo="
Write-EmbeddedFile -RelativePath "scripts\intelligence\Certify-AIOfficeIntelligenceUpgrade.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Test-AIOfficeEndToEndIntelligenceCertification.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.5-Part-K-End-to-End-Intelligence-Certification.md" -Base64Content ""
$Scripts = @(
"E:\AI\AI-Office\scripts\intelligence\Certify-AIOfficeIntelligenceUpgrade.ps1",
"E:\AI\AI-Office\scripts\intelligence\Test-AIOfficeEndToEndIntelligenceCertification.ps1")
foreach ($Script in $Scripts) {
  $Tokens=$null; $ParseErrors=$null
  [System.Management.Automation.Language.Parser]::ParseFile($Script,[ref]$Tokens,[ref]$ParseErrors)|Out-Null
  if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $Script + ": " + (($ParseErrors|ForEach-Object{$_.Message}) -join "; ")) }
}
Write-Host ""
Write-Host "AI Office v2.5 Part K End-to-End Intelligence Certification installed successfully." -ForegroundColor Green
Write-Host "No paid external inference was activated or executed." -ForegroundColor Cyan
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan